# =============================================================================
# DATABASE
# =============================================================================
#
# DEVELOPMENT:
#     DEBUG=True
#     -> SQLite
#
# PRODUCTION:
#     DEBUG=False
#     -> PostgreSQL through DATABASE_URL
#
# This preserves the existing development workflow and keeps PostgreSQL as
# the production database.
#

if DEBUG:
    DATABASES = {
        "default": {
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": BASE_DIR / "db.sqlite3",
            "OPTIONS": {"timeout": 20},
        }
    }

else:
    DATABASES = {
        "default": env.db("DATABASE_URL"),
    }


