# =============================================================================
# DJANGO REST FRAMEWORK
# =============================================================================
#
# SessionAuthentication remains enabled so the existing admin/browser
# workflows are not broken.
#
# TokenAuthentication is added for API clients/frontend integrations.
#

REST_FRAMEWORK = {
    "DEFAULT_AUTHENTICATION_CLASSES": [
        "users.authentication.LastSeenTokenAuthentication",
        "rest_framework.authentication.SessionAuthentication",
    ],

    "DEFAULT_PERMISSION_CLASSES": [
        "rest_framework.permissions.IsAuthenticated",
    ],

    "DEFAULT_PAGINATION_CLASS": (
        "rest_framework.pagination.PageNumberPagination"
    ),

    "PAGE_SIZE": 50,

    # Centralized security/audit handling for 401/403.
    "EXCEPTION_HANDLER": (
        "core.exception_handlers.audit_logging_exception_handler"
    ),
}


